from collections import deque
R, C = len(grid), len(grid[0])
start = None
for r in range(R):
    for c in range(C):
        if grid[r][c] == 'S':
            start = (r, c)
            break
    if start:
        break
if not start:
    return -1

# Queue: (r, c, keys_collected, steps)
queue = deque([(start[0], start[1], 0, 0)])
# Visited: (r, c, keys_collected)
visited = {(start[0], start[1], 0)}

while queue:
    r, c, k, steps = queue.popleft()
    if grid[r][c] == 'E' and k == 3:
        return steps

    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != '#':
            nk = k
            if grid[nr][nc] == 'K' and k < 3:
                # Only collect if we don't already have 3
                nk = k + 1
            if (nr, nc, nk) not in visited:
                visited.add((nr, nc, nk))
                queue.append((nr, nc, nk, steps + 1))
return -1

